/**
 * Level B `/t/$` route — thin-handler contract (TDD).
 *
 * The pure addressing + verification (`parseDevThemeAssetPath`,
 * `resolveDevThemeAsset`) is pinned by `dev-theme-asset-serve.test.ts`.
 * This suite pins the glue the route file owns: splat extraction, the
 * three exact-name store reads, and the Response mapping (verified bytes
 * with immutable caching; every refusal 404 with `no-store`, never an
 * immutable directive on a refusal).
 *
 * NOTE: `src/routeTree.gen.ts` is auto-generated by the TanStack vite
 * plugin on dev/build and is untouched here, so the static route id is
 * captured through a `createFileRoute` mock — the file's runtime shape
 * (server GET handler) is what is exercised.
 */
import { describe, expect, it, vi, beforeEach } from "vitest";
import { fakeDb } from "@/lib/__fixtures__/fake-db";
import {
  metricRecorder,
  allowAllRateLimits,
} from "@/lib/__fixtures__/test-doubles";
import {
  createDevThemeReleaseStore,
  type DevThemeRelease,
} from "@/lib/dev-theme-review";
import {
  validateDevThemeBundle,
  type DevThemeBundleInput,
} from "@/lib/dev-theme-bundle";
import { DEV_THEME_RUNTIME_VERSION } from "@/lib/dev-theme-manifest";

type Recorder = ReturnType<typeof metricRecorder>;
const rec = vi.hoisted(() => ({ holder: null as Recorder | null }));
const dbHolder = vi.hoisted(() => ({
  db: null as ReturnType<typeof fakeDb> | null,
  client: null as unknown | null,
}));
const recorder = metricRecorder();
rec.holder = recorder;

vi.mock("@/lib/observability.server", () => rec.holder!.observability);
vi.mock("@/lib/rate-limit.server", () => allowAllRateLimits());
vi.mock("@tanstack/react-router", () => ({
  createFileRoute:
    (id: string) =>
    (config: {
      server: {
        handlers: Record<string, (args: unknown) => Promise<Response>>;
      };
    }) => ({ routeId: id, handlers: config.server.handlers }),
}));
vi.mock("@/lib/pricing.server", () => ({
  publicClient: () => dbHolder.client ?? dbHolder.db!.asClient(),
}));

const { installReviewedThemeBundle } =
  await import("@/lib/dev-theme-bundle-install");
const { Route } = await import("./t.$");

const MERCHANT = "22222222-2222-2222-2222-222222222222";
const SELLER = "11111111-1111-1111-1111-111111111111";
const ACTOR = "99999999-9999-4999-8999-999999999999";
const LISTING_ID = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
const THEME_SLUG = "aurora-lookbook";
const T0 = "2026-10-01T00:00:00.000Z";
const T1 = "2026-10-02T00:00:00.000Z";
const MOD = { id: "reviewer-1", role: "moderator" } as const;
const GSAP_DEP = {
  name: "gsap",
  version: "3.15.0",
  license: "MIT",
  integrity: "sha384-AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
};

const HERO_JS = `export function HeroCanvas(el, props) { el.textContent = props.headline; }`;

function manifest(): Record<string, unknown> {
  return {
    id: THEME_SLUG,
    version: "1.0.0",
    runtime: DEV_THEME_RUNTIME_VERSION,
    name: "Aurora Lookbook",
    publisher: "Studio Framique",
    capabilities: ["presentation"],
    dependencies: [{ ...GSAP_DEP }],
    sections: [{ key: "hero", slot: "main", component: "HeroCanvas" }],
    settings: [{ key: "headline", label: "Headline", type: "text" }],
  };
}

function bundleInput(): DevThemeBundleInput {
  const m = manifest();
  return {
    manifest: m,
    files: [
      {
        path: "dev.theme.json",
        bytes: new TextEncoder().encode(JSON.stringify(m)),
      },
      { path: "components/Hero.js", bytes: new TextEncoder().encode(HERO_JS) },
    ],
    dependencies: [{ ...GSAP_DEP }],
    allowedNetworkHosts: [],
  };
}

async function installedDb() {
  const db = fakeDb({
    tables: {
      marketplace_themes: [],
      marketplace_installs: [],
      store_themes: [],
      theme_versions: [],
      theme_drafts: [],
      activity_log: [],
      theme_audit: [],
      wallet_ledger_entries: [],
      theme_assets: [],
    },
  });
  const store = createDevThemeReleaseStore();
  const v = validateDevThemeBundle(bundleInput());
  expect(v.ok).toBe(true);
  if (!v.ok) throw new Error("fixture bundle rejected");
  const { release: submitted } = store.submit({
    merchantId: SELLER,
    themeId: THEME_SLUG,
    manifest: v.manifest,
    files: v.files,
    fingerprint: v.fingerprint,
    submittedBy: "dev-1",
    submittedAt: T0,
  });
  store.review({
    releaseId: submitted.id,
    merchantId: SELLER,
    reviewer: { ...MOD },
    decision: "approve",
    reason: "clean",
    reviewedAt: T1,
  });
  const { release } = store.publish({
    releaseId: submitted.id,
    merchantId: SELLER,
    actor: { ...MOD },
    expectedFingerprint: v.fingerprint,
    publishedAt: T1,
  });
  await installReviewedThemeBundle(db.asClient(), MERCHANT, {
    release: release as DevThemeRelease,
    bytes: bundleInput(),
    idempotencyKey: "dev-route-1",
    listing: {
      id: LISTING_ID,
      slug: THEME_SLUG,
      name: "Aurora Lookbook",
      version: "1.0.0",
      price_minor_int: 0,
      currency_code: "BDT",
      seller_merchant_id: SELLER,
      install_count: 0,
    },
    trial: false,
    consentedBy: ACTOR,
    expectedThemeId: THEME_SLUG,
  });
  return db;
}

async function get(splat: string): Promise<Response> {
  const handlers = (
    Route as unknown as {
      handlers: Record<string, (args: unknown) => Promise<Response>>;
    }
  ).handlers;
  return handlers.GET({
    request: new Request(`https://shop.example/t/${splat}`),
    params: { _splat: splat },
  });
}

beforeEach(() => recorder.reset());

describe("/t/$ handler", () => {
  it("serves verified bytes with immutable caching", async () => {
    dbHolder.db = await installedDb();
    const assets = dbHolder.db.rows("theme_assets") as { name: string }[];
    const js = assets.find((a) => a.name.endsWith(".js"))!;
    const splat = js.name.replace("dev-themes/", "");
    const res = await get(splat);
    expect(res.status).toBe(200);
    expect(res.headers.get("content-type")).toContain("javascript");
    expect(res.headers.get("x-content-type-options")).toBe("nosniff");
    // Opaque-frame CORS: the sandboxed frame fetches modules in CORS mode.
    expect(res.headers.get("access-control-allow-origin")).toBe("*");
    expect(res.headers.get("cache-control")).toBe(
      "public, max-age=31536000, immutable",
    );
    expect(await res.text()).toBe(HERO_JS);
  });

  it("refuses traversal, unknown versions, and refused kinds with no-store 404s", async () => {
    dbHolder.db = await installedDb();
    for (const splat of [
      "aurora-lookbook/1.0.0/../secret",
      "aurora-lookbook/1.0.0/%2e%2e/secret",
      "aurora-lookbook/9.9.9/components/Hero.js",
      "aurora-lookbook/9.9.9/index.html",
      "aurora-lookbook/latest/components/Hero.js",
      "aurora-lookbook/latest/index.html",
    ]) {
      const res = await get(splat);
      expect(`${splat}: ${res.status}`).toBe(`${splat}: 404`);
      expect(res.headers.get("cache-control")).toBe("no-store");
    }
  });

  describe("index.html document lane", () => {
    it("serves the synthesized document with pinned tags + frame CSP + immutable caching", async () => {
      dbHolder.db = await installedDb();
      const res = await get("aurora-lookbook/1.0.0/index.html");
      expect(res.status).toBe(200);
      expect(res.headers.get("content-type")).toBe("text/html; charset=utf-8");
      expect(res.headers.get("x-content-type-options")).toBe("nosniff");
      expect(res.headers.get("access-control-allow-origin")).toBe("*");
      expect(res.headers.get("cache-control")).toBe(
        "public, max-age=31536000, immutable",
      );
      // CSP header is the ThemeRuntime frame contract for the serving origin
      // (the request URL host — https://shop.example in this harness).
      const { themeFrameCSP } =
        await import("@/components/theme-runtime/ThemeRuntime");
      expect(res.headers.get("content-security-policy")).toBe(
        themeFrameCSP("https://shop.example"),
      );
      const doc = await res.text();
      const assets = dbHolder.db.rows("theme_assets") as { name: string }[];
      const js = assets.find((a) => a.name.endsWith(".js"))!;
      const jsPath = js.name.replace("dev-themes/", "/t/");
      // Exact pinned tag, no inline code anywhere.
      expect(doc).toContain(`<script type="module" src="${jsPath}"></script>`);
      const scriptTags = doc.match(/<script[^>]*>/g) ?? [];
      expect(scriptTags.length).toBeGreaterThan(0);
      for (const tag of scriptTags) expect(tag).toContain("src=");
      for (const needle of ["onload=", "onerror=", "javascript:", "<style"]) {
        expect(
          doc.includes(needle),
          `document must not contain ${needle}`,
        ).toBe(false);
      }
    });

    it("404s the document when a referenced asset row drifts (byte leg)", async () => {
      dbHolder.db = await installedDb();
      const rows = dbHolder.db.rows("theme_assets") as { name: string }[];
      const idx = rows.findIndex((a) => a.name.endsWith(".js"));
      expect(idx).toBeGreaterThanOrEqual(0);
      rows.splice(idx, 1);
      const res = await get("aurora-lookbook/1.0.0/index.html");
      expect(res.status).toBe(404);
      expect(res.headers.get("cache-control")).toBe("no-store");
    });
  });

  describe("serve-time revocation re-check (Pass 2)", () => {
    async function installedDbWithLive(
      live: "published" | "revoked" | "removed" | null,
    ) {
      const db = fakeDb({
        tables: {
          marketplace_themes: [],
          marketplace_installs: [],
          store_themes: [],
          theme_versions: [],
          theme_drafts: [],
          activity_log: [],
          theme_audit: [],
          wallet_ledger_entries: [],
          theme_assets: [],
          dev_theme_releases: [],
          dev_theme_reviews: [],
        },
      });
      const store = createDevThemeReleaseStore();
      const v = validateDevThemeBundle(bundleInput());
      expect(v.ok).toBe(true);
      if (!v.ok) throw new Error("fixture bundle rejected");
      const { release: submitted } = store.submit({
        merchantId: SELLER,
        themeId: THEME_SLUG,
        manifest: v.manifest,
        files: v.files,
        fingerprint: v.fingerprint,
        submittedBy: "dev-1",
        submittedAt: T0,
      });
      store.review({
        releaseId: submitted.id,
        merchantId: SELLER,
        reviewer: { ...MOD },
        decision: "approve",
        reason: "clean",
        reviewedAt: T1,
      });
      const { release } = store.publish({
        releaseId: submitted.id,
        merchantId: SELLER,
        actor: { ...MOD },
        expectedFingerprint: v.fingerprint,
        publishedAt: T1,
      });
      await installReviewedThemeBundle(db.asClient(), MERCHANT, {
        release: release as DevThemeRelease,
        bytes: bundleInput(),
        idempotencyKey: "dev-route-live-1",
        listing: {
          id: LISTING_ID,
          slug: THEME_SLUG,
          name: "Aurora Lookbook",
          version: "1.0.0",
          price_minor_int: 0,
          currency_code: "BDT",
          seller_merchant_id: SELLER,
          install_count: 0,
        },
        trial: false,
        consentedBy: ACTOR,
        expectedThemeId: THEME_SLUG,
      });
      if (live) {
        db.rows("dev_theme_releases").push({
          merchant_id: SELLER,
          theme_id: THEME_SLUG,
          version: "1.0.0",
          fingerprint: v.fingerprint,
          status: live,
          submitted_by: "dev-1",
          submitted_at: T0,
        });
      }
      return { db, fingerprint: v.fingerprint };
    }

    async function jsSplat(): Promise<string> {
      const assets = dbHolder.db!.rows("theme_assets") as { name: string }[];
      const js = assets.find((a) => a.name.endsWith(".js"))!;
      return js.name.replace("dev-themes/", "");
    }

    beforeEach(() => {
      dbHolder.client = null;
    });

    it("serves when the live release row is still published", async () => {
      const { db } = await installedDbWithLive("published");
      dbHolder.db = db;
      const res = await get(await jsSplat());
      expect(res.status).toBe(200);
      expect(await res.text()).toBe(HERO_JS);
    });

    it("404s a revoked release even with a valid snapshot (fail-closed)", async () => {
      const { db } = await installedDbWithLive("revoked");
      dbHolder.db = db;
      const res = await get(await jsSplat());
      expect(res.status).toBe(404);
      expect(res.headers.get("cache-control")).toBe("no-store");
    });

    it("404s a removed (compromised) release even with a valid snapshot", async () => {
      const { db } = await installedDbWithLive("removed");
      dbHolder.db = db;
      const res = await get(await jsSplat());
      expect(res.status).toBe(404);
      expect(res.headers.get("cache-control")).toBe("no-store");
    });

    it("404s the index.html document for a revoked release", async () => {
      const { db } = await installedDbWithLive("revoked");
      dbHolder.db = db;
      const res = await get("aurora-lookbook/1.0.0/index.html");
      expect(res.status).toBe(404);
      expect(res.headers.get("cache-control")).toBe("no-store");
    });

    it("serves from the snapshot when no live row exists (pre-migration legacy)", async () => {
      const { db } = await installedDbWithLive(null);
      dbHolder.db = db;
      const res = await get(await jsSplat());
      expect(res.status).toBe(200);
    });

    it("404s fail-closed when the live store read faults", async () => {
      const { db } = await installedDbWithLive("published");
      dbHolder.db = db;
      const real = db.asClient() as {
        from: (table: string) => unknown;
      };
      const inner = real.from.bind(real);
      dbHolder.client = {
        from: (table: string) => {
          if (table === "dev_theme_releases")
            throw new Error("injected_live_store_outage");
          return inner(table);
        },
      };
      const res = await get(await jsSplat());
      expect(res.status).toBe(404);
      expect(res.headers.get("cache-control")).toBe("no-store");
    });
  });
});
